import { dsaCheatSheetData } from '@/data/dsaCheatSheet';

export interface PDFGenerationOptions {
  language: 'cpp' | 'java' | 'python' | 'javascript';
  includeComplexity: boolean;
  includeCode: boolean;
  includeKeyPoints: boolean;
  selectedTopics?: string[];
}

export class DSAPDFGenerator {
  private static generateHeader(): string {
    return `
# DSA Quick Reference Cheat Sheet
*Generated by Interview Express*

---

## Table of Contents
${dsaCheatSheetData.map((topic, index) => `${index + 1}. ${topic.title}`).join('\n')}

---

`;
  }

  private static generateTopicSection(topic: any, options: PDFGenerationOptions): string {
    let content = `## ${topic.title}\n\n`;
    content += `*${topic.description}*\n\n`;

    topic.concepts.forEach((concept: any, index: number) => {
      content += `### ${index + 1}. ${concept.name}\n\n`;
      content += `${concept.description}\n\n`;

      if (options.includeComplexity && concept.complexity) {
        content += `**Complexity:**\n`;
        content += `- Time: \`${concept.complexity.time}\`\n`;
        content += `- Space: \`${concept.complexity.space}\`\n\n`;
      }

      if (options.includeCode && concept.code && concept.code[options.language]) {
        content += `**Implementation (${options.language.toUpperCase()}):**\n\n`;
        content += '```' + options.language + '\n';
        content += concept.code[options.language];
        content += '\n```\n\n';
      }

      if (options.includeKeyPoints && concept.keyPoints && concept.keyPoints.length > 0) {
        content += `**Key Points:**\n`;
        concept.keyPoints.forEach((point: string) => {
          content += `- ${point}\n`;
        });
        content += '\n';
      }

      content += '---\n\n';
    });

    return content;
  }

  public static generateMarkdown(options: PDFGenerationOptions): string {
    let content = this.generateHeader();

    const topicsToInclude = options.selectedTopics 
      ? dsaCheatSheetData.filter((_, index) => options.selectedTopics!.includes(`topic-${index}`))
      : dsaCheatSheetData;

    topicsToInclude.forEach(topic => {
      content += this.generateTopicSection(topic, options);
    });

    content += `
---

## Additional Resources

### Online Platforms
- **LeetCode**: https://leetcode.com/
- **HackerRank**: https://hackerrank.com/
- **Codeforces**: https://codeforces.com/
- **GeeksforGeeks**: https://geeksforgeeks.org/

### Learning Resources
- **Striver's A2Z DSA Course**: https://takeuforward.org/dsa/strivers-a2z-sheet-learn-dsa-a-to-z
- **Company-wise Questions**: https://nextleet.com/search/sheet

### Books
- "Introduction to Algorithms" by Cormen, Leiserson, Rivest, and Stein
- "Algorithms" by Robert Sedgewick and Kevin Wayne
- "Cracking the Coding Interview" by Gayle Laakmann McDowell

---

*Generated on ${new Date().toLocaleDateString()} by Interview Express*
*Your complete DSA preparation platform*
`;

    return content;
  }

  public static async downloadPDF(options: PDFGenerationOptions): Promise<void> {
    try {
      const markdown = this.generateMarkdown(options);
      
      // Create a blob with the markdown content
      const blob = new Blob([markdown], { type: 'text/markdown' });
      
      // Create download link
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `DSA-CheatSheet-${options.language.toUpperCase()}-${new Date().toISOString().split('T')[0]}.md`;
      
      // Trigger download
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      
      // Clean up
      URL.revokeObjectURL(url);
      
      // In a real implementation, you would convert markdown to PDF using a library like:
      // - puppeteer
      // - jsPDF with markdown-pdf
      // - html2pdf.js
      // For now, we're downloading as markdown which can be converted to PDF using tools like pandoc
      
    } catch (error) {
      console.error('Error generating PDF:', error);
      throw new Error('Failed to generate PDF. Please try again.');
    }
  }

  public static getLanguageTemplates() {
    return {
      cpp: {
        name: 'C++',
        extension: 'cpp',
        comment: '//',
        includes: '#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;'
      },
      java: {
        name: 'Java',
        extension: 'java',
        comment: '//',
        includes: 'import java.util.*;\nimport java.io.*;'
      },
      python: {
        name: 'Python',
        extension: 'py',
        comment: '#',
        includes: 'import sys\nfrom collections import *\nfrom typing import *'
      },
      javascript: {
        name: 'JavaScript',
        extension: 'js',
        comment: '//',
        includes: '// Common utility functions\nconst log = console.log;'
      }
    };
  }
}

// Utility function for quick PDF generation with default options
export const generateDSACheatSheetPDF = async (language: 'cpp' | 'java' | 'python' | 'javascript' = 'cpp') => {
  const options: PDFGenerationOptions = {
    language,
    includeComplexity: true,
    includeCode: true,
    includeKeyPoints: true
  };
  
  await DSAPDFGenerator.downloadPDF(options);
};